printChar MACRO char
    mov AH,02h
    mov DL,char
    int 21h
ENDM

.MODEL
.STACK
.DATA
    COND db 10d
    COND2 db 10b
.CODE
    ;description
    main PROC
        mov DX,@data
        mov DS,DX
        xor DX,DX

        cmp COND2,10b
        je Z1

        cmp COND,10b
        je Z2
        jmp Z1

        Z1:
            printChar 'a'
            jmp Z3

        Z2:
            printChar 'b'
            jmp Z1

        Z3:

        .EXIT
    main ENDP

end main
